-- Original private contribution entries, implemented as local closed triggers. No quantity or money is accepted.
-- A command row names an original fact and an original build. It is deleted by its trigger before the statement returns.
CREATE TABLE metering_projection_apply (
 family TEXT NOT NULL CHECK(family IN('wallet','reporting','source')),organization_id TEXT NOT NULL,generation TEXT,
 source_kind TEXT NOT NULL CHECK((family='wallet' AND source_kind IN('grant','movement','reservation','resolution')) OR (family='reporting' AND source_kind IN('reservation','resolution')) OR (family='source' AND source_kind IN('valuation','movement'))),source_key TEXT NOT NULL,marked INTEGER NOT NULL CHECK(marked IN(0,1)),
 source_reference TEXT,resource_kind TEXT,eligible INTEGER NOT NULL DEFAULT 0,delta TEXT NOT NULL DEFAULT '0',next_net TEXT NOT NULL DEFAULT '0'
) STRICT;
CREATE TRIGGER metering_projection_apply_wallet AFTER INSERT ON metering_projection_apply WHEN NEW.family='wallet' BEGIN
 SELECT RAISE(ABORT,'credit_projection_source_missing') WHERE (NEW.marked=0 OR NOT EXISTS(SELECT 1 FROM credit_projection_build_applied a WHERE a.organization_id=NEW.organization_id AND a.generation=NEW.generation AND a.source_kind=NEW.source_kind AND a.source_key=NEW.source_key)) AND NOT (CASE NEW.source_kind WHEN 'grant' THEN EXISTS(SELECT 1 FROM credit_lots WHERE organization_id=NEW.organization_id AND grant_id=NEW.source_key) WHEN 'movement' THEN EXISTS(SELECT 1 FROM metering_projection_movements m WHERE m.organization_id=NEW.organization_id AND m.reservation_id=substr(NEW.source_key,1,26) AND m.grant_id=substr(NEW.source_key,28,26) AND m.phase=substr(NEW.source_key,55)) WHEN 'reservation' THEN EXISTS(SELECT 1 FROM metering_projection_reservations WHERE organization_id=NEW.organization_id AND reservation_id=NEW.source_key) WHEN 'resolution' THEN EXISTS(SELECT 1 FROM metering_projection_resolutions x JOIN metering_projection_reservations r USING(reservation_id) WHERE r.organization_id=NEW.organization_id AND x.reservation_id=NEW.source_key) ELSE 0 END);
 INSERT INTO credit_lot_totals(organization_id,generation,grant_id,reserved_micros,spent_micros) SELECT NEW.organization_id,NEW.generation,NEW.source_key,'0','0' WHERE NEW.source_kind='grant' AND (NEW.marked=0 OR NOT EXISTS(SELECT 1 FROM credit_projection_build_applied a WHERE a.organization_id=NEW.organization_id AND a.generation=NEW.generation AND a.source_kind=NEW.source_kind AND a.source_key=NEW.source_key)) ON CONFLICT DO NOTHING;
 INSERT INTO credit_lot_totals(organization_id,generation,grant_id,reserved_micros,spent_micros) SELECT NEW.organization_id,NEW.generation,grant_id,CAST(reserved_micros AS TEXT),CAST(spent_micros AS TEXT) FROM metering_projection_movements m WHERE NEW.source_kind='movement' AND (NEW.marked=0 OR NOT EXISTS(SELECT 1 FROM credit_projection_build_applied a WHERE a.organization_id=NEW.organization_id AND a.generation=NEW.generation AND a.source_kind=NEW.source_kind AND a.source_key=NEW.source_key)) AND m.organization_id=NEW.organization_id AND m.reservation_id=substr(NEW.source_key,1,26) AND m.grant_id=substr(NEW.source_key,28,26) AND m.phase=substr(NEW.source_key,55) ON CONFLICT(organization_id,generation,grant_id) DO UPDATE SET reserved_micros=(WITH RECURSIVE raw(a,b) AS (SELECT coalesce(credit_lot_totals.reserved_micros,'0'),coalesce(excluded.reserved_micros,'0')), mags AS (SELECT ltrim(a,'-') AS x,ltrim(b,'-') AS y,substr(a,1,1)='-' AS sa,substr(b,1,1)='-' AS sb FROM raw), args AS (SELECT CASE WHEN length(x)>length(y) OR (length(x)=length(y) AND x>=y) THEN x ELSE y END AS x,CASE WHEN length(x)>length(y) OR (length(x)=length(y) AND x>=y) THEN y ELSE x END AS y,CASE WHEN sa=sb THEN 1 ELSE -1 END AS op,CASE WHEN sa=sb OR length(x)>length(y) OR (length(x)=length(y) AND x>=y) THEN sa ELSE sb END AS neg FROM mags), digits(i,carry,out) AS (SELECT 0,0,'' UNION ALL SELECT i+1,CASE WHEN CAST(substr('0'||x,-i-1,1) AS INTEGER)+op*CAST(substr('0'||y,-i-1,1) AS INTEGER)+carry<0 THEN -1 ELSE (CAST(substr('0'||x,-i-1,1) AS INTEGER)+op*CAST(substr('0'||y,-i-1,1) AS INTEGER)+carry)/10 END,CAST((CAST(substr('0'||x,-i-1,1) AS INTEGER)+op*CAST(substr('0'||y,-i-1,1) AS INTEGER)+carry+10)%10 AS TEXT)||out FROM digits,args WHERE i<max(length(x),length(y))) SELECT CASE WHEN trim(CASE WHEN carry>0 THEN CAST(carry AS TEXT)||out ELSE out END,'0')='' THEN '0' ELSE CASE WHEN neg THEN '-' ELSE '' END||ltrim(CASE WHEN carry>0 THEN CAST(carry AS TEXT)||out ELSE out END,'0') END FROM digits,args WHERE i=max(length(x),length(y))),spent_micros=(WITH RECURSIVE raw(a,b) AS (SELECT coalesce(credit_lot_totals.spent_micros,'0'),coalesce(excluded.spent_micros,'0')), mags AS (SELECT ltrim(a,'-') AS x,ltrim(b,'-') AS y,substr(a,1,1)='-' AS sa,substr(b,1,1)='-' AS sb FROM raw), args AS (SELECT CASE WHEN length(x)>length(y) OR (length(x)=length(y) AND x>=y) THEN x ELSE y END AS x,CASE WHEN length(x)>length(y) OR (length(x)=length(y) AND x>=y) THEN y ELSE x END AS y,CASE WHEN sa=sb THEN 1 ELSE -1 END AS op,CASE WHEN sa=sb OR length(x)>length(y) OR (length(x)=length(y) AND x>=y) THEN sa ELSE sb END AS neg FROM mags), digits(i,carry,out) AS (SELECT 0,0,'' UNION ALL SELECT i+1,CASE WHEN CAST(substr('0'||x,-i-1,1) AS INTEGER)+op*CAST(substr('0'||y,-i-1,1) AS INTEGER)+carry<0 THEN -1 ELSE (CAST(substr('0'||x,-i-1,1) AS INTEGER)+op*CAST(substr('0'||y,-i-1,1) AS INTEGER)+carry)/10 END,CAST((CAST(substr('0'||x,-i-1,1) AS INTEGER)+op*CAST(substr('0'||y,-i-1,1) AS INTEGER)+carry+10)%10 AS TEXT)||out FROM digits,args WHERE i<max(length(x),length(y))) SELECT CASE WHEN trim(CASE WHEN carry>0 THEN CAST(carry AS TEXT)||out ELSE out END,'0')='' THEN '0' ELSE CASE WHEN neg THEN '-' ELSE '' END||ltrim(CASE WHEN carry>0 THEN CAST(carry AS TEXT)||out ELSE out END,'0') END FROM digits,args WHERE i=max(length(x),length(y)));
 INSERT INTO credit_project_outstanding(organization_id,generation,project_id,amount_micros,open_reservations) SELECT NEW.organization_id,NEW.generation,r.project_id,CAST(r.amount_micros AS TEXT),1 FROM metering_projection_reservations r WHERE NEW.source_kind='reservation' AND (NEW.marked=0 OR NOT EXISTS(SELECT 1 FROM credit_projection_build_applied a WHERE a.organization_id=NEW.organization_id AND a.generation=NEW.generation AND a.source_kind=NEW.source_kind AND a.source_key=NEW.source_key)) AND r.organization_id=NEW.organization_id AND r.reservation_id=NEW.source_key ON CONFLICT(organization_id,generation,project_id) DO UPDATE SET amount_micros=(WITH RECURSIVE raw(a,b) AS (SELECT coalesce(credit_project_outstanding.amount_micros,'0'),coalesce(excluded.amount_micros,'0')), mags AS (SELECT ltrim(a,'-') AS x,ltrim(b,'-') AS y,substr(a,1,1)='-' AS sa,substr(b,1,1)='-' AS sb FROM raw), args AS (SELECT CASE WHEN length(x)>length(y) OR (length(x)=length(y) AND x>=y) THEN x ELSE y END AS x,CASE WHEN length(x)>length(y) OR (length(x)=length(y) AND x>=y) THEN y ELSE x END AS y,CASE WHEN sa=sb THEN 1 ELSE -1 END AS op,CASE WHEN sa=sb OR length(x)>length(y) OR (length(x)=length(y) AND x>=y) THEN sa ELSE sb END AS neg FROM mags), digits(i,carry,out) AS (SELECT 0,0,'' UNION ALL SELECT i+1,CASE WHEN CAST(substr('0'||x,-i-1,1) AS INTEGER)+op*CAST(substr('0'||y,-i-1,1) AS INTEGER)+carry<0 THEN -1 ELSE (CAST(substr('0'||x,-i-1,1) AS INTEGER)+op*CAST(substr('0'||y,-i-1,1) AS INTEGER)+carry)/10 END,CAST((CAST(substr('0'||x,-i-1,1) AS INTEGER)+op*CAST(substr('0'||y,-i-1,1) AS INTEGER)+carry+10)%10 AS TEXT)||out FROM digits,args WHERE i<max(length(x),length(y))) SELECT CASE WHEN trim(CASE WHEN carry>0 THEN CAST(carry AS TEXT)||out ELSE out END,'0')='' THEN '0' ELSE CASE WHEN neg THEN '-' ELSE '' END||ltrim(CASE WHEN carry>0 THEN CAST(carry AS TEXT)||out ELSE out END,'0') END FROM digits,args WHERE i=max(length(x),length(y))),open_reservations=open_reservations+excluded.open_reservations;
 INSERT INTO credit_project_outstanding(organization_id,generation,project_id,amount_micros,open_reservations) SELECT NEW.organization_id,NEW.generation,r.project_id,CAST(-r.amount_micros AS TEXT),-1 FROM metering_projection_reservations r JOIN metering_projection_resolutions x USING(reservation_id) WHERE NEW.source_kind='resolution' AND (NEW.marked=0 OR NOT EXISTS(SELECT 1 FROM credit_projection_build_applied a WHERE a.organization_id=NEW.organization_id AND a.generation=NEW.generation AND a.source_kind=NEW.source_kind AND a.source_key=NEW.source_key)) AND r.organization_id=NEW.organization_id AND r.reservation_id=NEW.source_key ON CONFLICT(organization_id,generation,project_id) DO UPDATE SET amount_micros=(WITH RECURSIVE raw(a,b) AS (SELECT coalesce(credit_project_outstanding.amount_micros,'0'),coalesce(excluded.amount_micros,'0')), mags AS (SELECT ltrim(a,'-') AS x,ltrim(b,'-') AS y,substr(a,1,1)='-' AS sa,substr(b,1,1)='-' AS sb FROM raw), args AS (SELECT CASE WHEN length(x)>length(y) OR (length(x)=length(y) AND x>=y) THEN x ELSE y END AS x,CASE WHEN length(x)>length(y) OR (length(x)=length(y) AND x>=y) THEN y ELSE x END AS y,CASE WHEN sa=sb THEN 1 ELSE -1 END AS op,CASE WHEN sa=sb OR length(x)>length(y) OR (length(x)=length(y) AND x>=y) THEN sa ELSE sb END AS neg FROM mags), digits(i,carry,out) AS (SELECT 0,0,'' UNION ALL SELECT i+1,CASE WHEN CAST(substr('0'||x,-i-1,1) AS INTEGER)+op*CAST(substr('0'||y,-i-1,1) AS INTEGER)+carry<0 THEN -1 ELSE (CAST(substr('0'||x,-i-1,1) AS INTEGER)+op*CAST(substr('0'||y,-i-1,1) AS INTEGER)+carry)/10 END,CAST((CAST(substr('0'||x,-i-1,1) AS INTEGER)+op*CAST(substr('0'||y,-i-1,1) AS INTEGER)+carry+10)%10 AS TEXT)||out FROM digits,args WHERE i<max(length(x),length(y))) SELECT CASE WHEN trim(CASE WHEN carry>0 THEN CAST(carry AS TEXT)||out ELSE out END,'0')='' THEN '0' ELSE CASE WHEN neg THEN '-' ELSE '' END||ltrim(CASE WHEN carry>0 THEN CAST(carry AS TEXT)||out ELSE out END,'0') END FROM digits,args WHERE i=max(length(x),length(y))),open_reservations=open_reservations+excluded.open_reservations;
 UPDATE credit_org_exposure SET resolution_unfunded_micros=(WITH RECURSIVE raw(a,b) AS (SELECT coalesce(resolution_unfunded_micros,'0'),coalesce((SELECT CAST(x.charge_micros-x.funded_micros AS TEXT) FROM metering_projection_resolutions x WHERE x.reservation_id=NEW.source_key),'0')), mags AS (SELECT ltrim(a,'-') AS x,ltrim(b,'-') AS y,substr(a,1,1)='-' AS sa,substr(b,1,1)='-' AS sb FROM raw), args AS (SELECT CASE WHEN length(x)>length(y) OR (length(x)=length(y) AND x>=y) THEN x ELSE y END AS x,CASE WHEN length(x)>length(y) OR (length(x)=length(y) AND x>=y) THEN y ELSE x END AS y,CASE WHEN sa=sb THEN 1 ELSE -1 END AS op,CASE WHEN sa=sb OR length(x)>length(y) OR (length(x)=length(y) AND x>=y) THEN sa ELSE sb END AS neg FROM mags), digits(i,carry,out) AS (SELECT 0,0,'' UNION ALL SELECT i+1,CASE WHEN CAST(substr('0'||x,-i-1,1) AS INTEGER)+op*CAST(substr('0'||y,-i-1,1) AS INTEGER)+carry<0 THEN -1 ELSE (CAST(substr('0'||x,-i-1,1) AS INTEGER)+op*CAST(substr('0'||y,-i-1,1) AS INTEGER)+carry)/10 END,CAST((CAST(substr('0'||x,-i-1,1) AS INTEGER)+op*CAST(substr('0'||y,-i-1,1) AS INTEGER)+carry+10)%10 AS TEXT)||out FROM digits,args WHERE i<max(length(x),length(y))) SELECT CASE WHEN trim(CASE WHEN carry>0 THEN CAST(carry AS TEXT)||out ELSE out END,'0')='' THEN '0' ELSE CASE WHEN neg THEN '-' ELSE '' END||ltrim(CASE WHEN carry>0 THEN CAST(carry AS TEXT)||out ELSE out END,'0') END FROM digits,args WHERE i=max(length(x),length(y))) WHERE organization_id=NEW.organization_id AND generation=NEW.generation AND NEW.source_kind='resolution' AND (NEW.marked=0 OR NOT EXISTS(SELECT 1 FROM credit_projection_build_applied a WHERE a.organization_id=NEW.organization_id AND a.generation=NEW.generation AND a.source_kind=NEW.source_kind AND a.source_key=NEW.source_key));
 INSERT INTO credit_project_period_totals(organization_id,generation,project_id,event_month,charged_micros) SELECT NEW.organization_id,NEW.generation,r.project_id,substr(x.event_time,1,7)||'-01',CAST(x.charge_micros AS TEXT) FROM metering_projection_resolutions x JOIN metering_projection_reservations r USING(reservation_id) WHERE NEW.source_kind='resolution' AND (NEW.marked=0 OR NOT EXISTS(SELECT 1 FROM credit_projection_build_applied a WHERE a.organization_id=NEW.organization_id AND a.generation=NEW.generation AND a.source_kind=NEW.source_kind AND a.source_key=NEW.source_key)) AND r.organization_id=NEW.organization_id AND r.reservation_id=NEW.source_key AND x.outcome IN('settled','corrected') ON CONFLICT(organization_id,generation,project_id,event_month) DO UPDATE SET charged_micros=(WITH RECURSIVE raw(a,b) AS (SELECT coalesce(credit_project_period_totals.charged_micros,'0'),coalesce(excluded.charged_micros,'0')), mags AS (SELECT ltrim(a,'-') AS x,ltrim(b,'-') AS y,substr(a,1,1)='-' AS sa,substr(b,1,1)='-' AS sb FROM raw), args AS (SELECT CASE WHEN length(x)>length(y) OR (length(x)=length(y) AND x>=y) THEN x ELSE y END AS x,CASE WHEN length(x)>length(y) OR (length(x)=length(y) AND x>=y) THEN y ELSE x END AS y,CASE WHEN sa=sb THEN 1 ELSE -1 END AS op,CASE WHEN sa=sb OR length(x)>length(y) OR (length(x)=length(y) AND x>=y) THEN sa ELSE sb END AS neg FROM mags), digits(i,carry,out) AS (SELECT 0,0,'' UNION ALL SELECT i+1,CASE WHEN CAST(substr('0'||x,-i-1,1) AS INTEGER)+op*CAST(substr('0'||y,-i-1,1) AS INTEGER)+carry<0 THEN -1 ELSE (CAST(substr('0'||x,-i-1,1) AS INTEGER)+op*CAST(substr('0'||y,-i-1,1) AS INTEGER)+carry)/10 END,CAST((CAST(substr('0'||x,-i-1,1) AS INTEGER)+op*CAST(substr('0'||y,-i-1,1) AS INTEGER)+carry+10)%10 AS TEXT)||out FROM digits,args WHERE i<max(length(x),length(y))) SELECT CASE WHEN trim(CASE WHEN carry>0 THEN CAST(carry AS TEXT)||out ELSE out END,'0')='' THEN '0' ELSE CASE WHEN neg THEN '-' ELSE '' END||ltrim(CASE WHEN carry>0 THEN CAST(carry AS TEXT)||out ELSE out END,'0') END FROM digits,args WHERE i=max(length(x),length(y)));
 INSERT INTO credit_projection_build_applied SELECT NEW.organization_id,NEW.generation,NEW.source_kind,NEW.source_key WHERE NEW.marked=1 AND (NEW.marked=0 OR NOT EXISTS(SELECT 1 FROM credit_projection_build_applied a WHERE a.organization_id=NEW.organization_id AND a.generation=NEW.generation AND a.source_kind=NEW.source_kind AND a.source_key=NEW.source_key)) ON CONFLICT DO NOTHING;
 DELETE FROM metering_projection_apply WHERE rowid=NEW.rowid;
END;
CREATE TRIGGER metering_projection_apply_reporting AFTER INSERT ON metering_projection_apply WHEN NEW.family='reporting' BEGIN
 SELECT RAISE(ABORT,'credit_usage_reporting_source_missing') WHERE (NEW.marked=0 OR NOT EXISTS(SELECT 1 FROM credit_usage_reporting_build_applied a WHERE a.organization_id=NEW.organization_id AND a.generation=NEW.generation AND a.source_kind=NEW.source_kind AND a.source_key=NEW.source_key)) AND NOT EXISTS(SELECT 1 FROM (SELECT r.*,x.outcome,x.charge_micros,x.funded_micros,x.quantity,x.rate_card_id,x.meter,x.unit,x.event_time,x.resolved_at FROM metering_projection_reservations r LEFT JOIN metering_projection_resolutions x USING(reservation_id) WHERE r.organization_id=NEW.organization_id AND r.reservation_id=NEW.source_key) f WHERE NEW.source_kind='reservation' OR (NEW.source_kind='resolution' AND f.outcome IS NOT NULL));
 INSERT INTO credit_usage_project_holds(organization_id,generation,project_id,current_amount_micros,positive_open_count,first_positive_reserved_at,last_effective_at) SELECT NEW.organization_id,NEW.generation,f.project_id,CAST(CASE WHEN NEW.source_kind='reservation' THEN f.amount_micros ELSE -f.amount_micros END AS TEXT),CASE WHEN NEW.source_kind='reservation' THEN 1 ELSE -1 END,f.reserved_at,CASE WHEN NEW.source_kind='reservation' THEN f.reserved_at ELSE max(f.reserved_at,f.resolved_at) END FROM (SELECT r.*,x.outcome,x.charge_micros,x.funded_micros,x.quantity,x.rate_card_id,x.meter,x.unit,x.event_time,x.resolved_at FROM metering_projection_reservations r LEFT JOIN metering_projection_resolutions x USING(reservation_id) WHERE r.organization_id=NEW.organization_id AND r.reservation_id=NEW.source_key) f WHERE (NEW.marked=0 OR NOT EXISTS(SELECT 1 FROM credit_usage_reporting_build_applied a WHERE a.organization_id=NEW.organization_id AND a.generation=NEW.generation AND a.source_kind=NEW.source_kind AND a.source_key=NEW.source_key)) AND f.amount_micros>0 ON CONFLICT(organization_id,generation,project_id) DO UPDATE SET current_amount_micros=(WITH RECURSIVE raw(a,b) AS (SELECT coalesce(credit_usage_project_holds.current_amount_micros,'0'),coalesce(excluded.current_amount_micros,'0')), mags AS (SELECT ltrim(a,'-') AS x,ltrim(b,'-') AS y,substr(a,1,1)='-' AS sa,substr(b,1,1)='-' AS sb FROM raw), args AS (SELECT CASE WHEN length(x)>length(y) OR (length(x)=length(y) AND x>=y) THEN x ELSE y END AS x,CASE WHEN length(x)>length(y) OR (length(x)=length(y) AND x>=y) THEN y ELSE x END AS y,CASE WHEN sa=sb THEN 1 ELSE -1 END AS op,CASE WHEN sa=sb OR length(x)>length(y) OR (length(x)=length(y) AND x>=y) THEN sa ELSE sb END AS neg FROM mags), digits(i,carry,out) AS (SELECT 0,0,'' UNION ALL SELECT i+1,CASE WHEN CAST(substr('0'||x,-i-1,1) AS INTEGER)+op*CAST(substr('0'||y,-i-1,1) AS INTEGER)+carry<0 THEN -1 ELSE (CAST(substr('0'||x,-i-1,1) AS INTEGER)+op*CAST(substr('0'||y,-i-1,1) AS INTEGER)+carry)/10 END,CAST((CAST(substr('0'||x,-i-1,1) AS INTEGER)+op*CAST(substr('0'||y,-i-1,1) AS INTEGER)+carry+10)%10 AS TEXT)||out FROM digits,args WHERE i<max(length(x),length(y))) SELECT CASE WHEN trim(CASE WHEN carry>0 THEN CAST(carry AS TEXT)||out ELSE out END,'0')='' THEN '0' ELSE CASE WHEN neg THEN '-' ELSE '' END||ltrim(CASE WHEN carry>0 THEN CAST(carry AS TEXT)||out ELSE out END,'0') END FROM digits,args WHERE i=max(length(x),length(y))),positive_open_count=positive_open_count+excluded.positive_open_count,first_positive_reserved_at=min(first_positive_reserved_at,excluded.first_positive_reserved_at),last_effective_at=max(last_effective_at,excluded.last_effective_at);
 UPDATE credit_usage_dimension_sequence SET last_value=CASE WHEN is_called THEN last_value+1 ELSE last_value END,is_called=1 WHERE singleton=1 AND EXISTS(SELECT 1 FROM (SELECT r.*,x.outcome,x.charge_micros,x.funded_micros,x.quantity,x.rate_card_id,x.meter,x.unit,x.event_time,x.resolved_at FROM metering_projection_reservations r LEFT JOIN metering_projection_resolutions x USING(reservation_id) WHERE r.organization_id=NEW.organization_id AND r.reservation_id=NEW.source_key) f WHERE (NEW.marked=0 OR NOT EXISTS(SELECT 1 FROM credit_usage_reporting_build_applied a WHERE a.organization_id=NEW.organization_id AND a.generation=NEW.generation AND a.source_kind=NEW.source_kind AND a.source_key=NEW.source_key)) AND NEW.source_kind='resolution' AND f.outcome IN('settled','corrected') AND f.event_time NOT IN('infinity','-infinity') AND NOT EXISTS(SELECT 1 FROM credit_usage_dimensions d WHERE d.organization_id=NEW.organization_id AND d.generation=NEW.generation AND d.project_id=f.project_id AND d.environment_id IS f.environment_id AND d.event_month=substr(f.event_time,1,7)||'-01' AND d.rate_card_id=f.rate_card_id AND d.meter=f.meter AND d.unit=f.unit));
 INSERT INTO credit_usage_dimensions(organization_id,generation,dimension_id,project_id,event_month,environment_id,rate_card_id,meter,unit,quantity,charged_micros,funded_micros,platform_overrun_micros,report_row_count,first_visible_at,last_visible_at) SELECT NEW.organization_id,NEW.generation,(SELECT last_value FROM credit_usage_dimension_sequence WHERE singleton=1),f.project_id,substr(f.event_time,1,7)||'-01',f.environment_id,f.rate_card_id,f.meter,f.unit,CAST(f.quantity AS TEXT),CAST(f.charge_micros AS TEXT),CAST(f.funded_micros AS TEXT),CAST(f.charge_micros-f.funded_micros AS TEXT),1,CASE WHEN NEW.source_kind='reservation' THEN f.reserved_at ELSE max(f.reserved_at,f.resolved_at) END,CASE WHEN NEW.source_kind='reservation' THEN f.reserved_at ELSE max(f.reserved_at,f.resolved_at) END FROM (SELECT r.*,x.outcome,x.charge_micros,x.funded_micros,x.quantity,x.rate_card_id,x.meter,x.unit,x.event_time,x.resolved_at FROM metering_projection_reservations r LEFT JOIN metering_projection_resolutions x USING(reservation_id) WHERE r.organization_id=NEW.organization_id AND r.reservation_id=NEW.source_key) f WHERE (NEW.marked=0 OR NOT EXISTS(SELECT 1 FROM credit_usage_reporting_build_applied a WHERE a.organization_id=NEW.organization_id AND a.generation=NEW.generation AND a.source_kind=NEW.source_kind AND a.source_key=NEW.source_key)) AND NEW.source_kind='resolution' AND f.outcome IN('settled','corrected') AND f.event_time NOT IN('infinity','-infinity') ON CONFLICT DO UPDATE SET quantity=(WITH RECURSIVE raw(a,b) AS (SELECT coalesce(credit_usage_dimensions.quantity,'0'),coalesce(excluded.quantity,'0')), mags AS (SELECT ltrim(a,'-') AS x,ltrim(b,'-') AS y,substr(a,1,1)='-' AS sa,substr(b,1,1)='-' AS sb FROM raw), args AS (SELECT CASE WHEN length(x)>length(y) OR (length(x)=length(y) AND x>=y) THEN x ELSE y END AS x,CASE WHEN length(x)>length(y) OR (length(x)=length(y) AND x>=y) THEN y ELSE x END AS y,CASE WHEN sa=sb THEN 1 ELSE -1 END AS op,CASE WHEN sa=sb OR length(x)>length(y) OR (length(x)=length(y) AND x>=y) THEN sa ELSE sb END AS neg FROM mags), digits(i,carry,out) AS (SELECT 0,0,'' UNION ALL SELECT i+1,CASE WHEN CAST(substr('0'||x,-i-1,1) AS INTEGER)+op*CAST(substr('0'||y,-i-1,1) AS INTEGER)+carry<0 THEN -1 ELSE (CAST(substr('0'||x,-i-1,1) AS INTEGER)+op*CAST(substr('0'||y,-i-1,1) AS INTEGER)+carry)/10 END,CAST((CAST(substr('0'||x,-i-1,1) AS INTEGER)+op*CAST(substr('0'||y,-i-1,1) AS INTEGER)+carry+10)%10 AS TEXT)||out FROM digits,args WHERE i<max(length(x),length(y))) SELECT CASE WHEN trim(CASE WHEN carry>0 THEN CAST(carry AS TEXT)||out ELSE out END,'0')='' THEN '0' ELSE CASE WHEN neg THEN '-' ELSE '' END||ltrim(CASE WHEN carry>0 THEN CAST(carry AS TEXT)||out ELSE out END,'0') END FROM digits,args WHERE i=max(length(x),length(y))),charged_micros=(WITH RECURSIVE raw(a,b) AS (SELECT coalesce(credit_usage_dimensions.charged_micros,'0'),coalesce(excluded.charged_micros,'0')), mags AS (SELECT ltrim(a,'-') AS x,ltrim(b,'-') AS y,substr(a,1,1)='-' AS sa,substr(b,1,1)='-' AS sb FROM raw), args AS (SELECT CASE WHEN length(x)>length(y) OR (length(x)=length(y) AND x>=y) THEN x ELSE y END AS x,CASE WHEN length(x)>length(y) OR (length(x)=length(y) AND x>=y) THEN y ELSE x END AS y,CASE WHEN sa=sb THEN 1 ELSE -1 END AS op,CASE WHEN sa=sb OR length(x)>length(y) OR (length(x)=length(y) AND x>=y) THEN sa ELSE sb END AS neg FROM mags), digits(i,carry,out) AS (SELECT 0,0,'' UNION ALL SELECT i+1,CASE WHEN CAST(substr('0'||x,-i-1,1) AS INTEGER)+op*CAST(substr('0'||y,-i-1,1) AS INTEGER)+carry<0 THEN -1 ELSE (CAST(substr('0'||x,-i-1,1) AS INTEGER)+op*CAST(substr('0'||y,-i-1,1) AS INTEGER)+carry)/10 END,CAST((CAST(substr('0'||x,-i-1,1) AS INTEGER)+op*CAST(substr('0'||y,-i-1,1) AS INTEGER)+carry+10)%10 AS TEXT)||out FROM digits,args WHERE i<max(length(x),length(y))) SELECT CASE WHEN trim(CASE WHEN carry>0 THEN CAST(carry AS TEXT)||out ELSE out END,'0')='' THEN '0' ELSE CASE WHEN neg THEN '-' ELSE '' END||ltrim(CASE WHEN carry>0 THEN CAST(carry AS TEXT)||out ELSE out END,'0') END FROM digits,args WHERE i=max(length(x),length(y))),funded_micros=(WITH RECURSIVE raw(a,b) AS (SELECT coalesce(credit_usage_dimensions.funded_micros,'0'),coalesce(excluded.funded_micros,'0')), mags AS (SELECT ltrim(a,'-') AS x,ltrim(b,'-') AS y,substr(a,1,1)='-' AS sa,substr(b,1,1)='-' AS sb FROM raw), args AS (SELECT CASE WHEN length(x)>length(y) OR (length(x)=length(y) AND x>=y) THEN x ELSE y END AS x,CASE WHEN length(x)>length(y) OR (length(x)=length(y) AND x>=y) THEN y ELSE x END AS y,CASE WHEN sa=sb THEN 1 ELSE -1 END AS op,CASE WHEN sa=sb OR length(x)>length(y) OR (length(x)=length(y) AND x>=y) THEN sa ELSE sb END AS neg FROM mags), digits(i,carry,out) AS (SELECT 0,0,'' UNION ALL SELECT i+1,CASE WHEN CAST(substr('0'||x,-i-1,1) AS INTEGER)+op*CAST(substr('0'||y,-i-1,1) AS INTEGER)+carry<0 THEN -1 ELSE (CAST(substr('0'||x,-i-1,1) AS INTEGER)+op*CAST(substr('0'||y,-i-1,1) AS INTEGER)+carry)/10 END,CAST((CAST(substr('0'||x,-i-1,1) AS INTEGER)+op*CAST(substr('0'||y,-i-1,1) AS INTEGER)+carry+10)%10 AS TEXT)||out FROM digits,args WHERE i<max(length(x),length(y))) SELECT CASE WHEN trim(CASE WHEN carry>0 THEN CAST(carry AS TEXT)||out ELSE out END,'0')='' THEN '0' ELSE CASE WHEN neg THEN '-' ELSE '' END||ltrim(CASE WHEN carry>0 THEN CAST(carry AS TEXT)||out ELSE out END,'0') END FROM digits,args WHERE i=max(length(x),length(y))),platform_overrun_micros=(WITH RECURSIVE raw(a,b) AS (SELECT coalesce(credit_usage_dimensions.platform_overrun_micros,'0'),coalesce(excluded.platform_overrun_micros,'0')), mags AS (SELECT ltrim(a,'-') AS x,ltrim(b,'-') AS y,substr(a,1,1)='-' AS sa,substr(b,1,1)='-' AS sb FROM raw), args AS (SELECT CASE WHEN length(x)>length(y) OR (length(x)=length(y) AND x>=y) THEN x ELSE y END AS x,CASE WHEN length(x)>length(y) OR (length(x)=length(y) AND x>=y) THEN y ELSE x END AS y,CASE WHEN sa=sb THEN 1 ELSE -1 END AS op,CASE WHEN sa=sb OR length(x)>length(y) OR (length(x)=length(y) AND x>=y) THEN sa ELSE sb END AS neg FROM mags), digits(i,carry,out) AS (SELECT 0,0,'' UNION ALL SELECT i+1,CASE WHEN CAST(substr('0'||x,-i-1,1) AS INTEGER)+op*CAST(substr('0'||y,-i-1,1) AS INTEGER)+carry<0 THEN -1 ELSE (CAST(substr('0'||x,-i-1,1) AS INTEGER)+op*CAST(substr('0'||y,-i-1,1) AS INTEGER)+carry)/10 END,CAST((CAST(substr('0'||x,-i-1,1) AS INTEGER)+op*CAST(substr('0'||y,-i-1,1) AS INTEGER)+carry+10)%10 AS TEXT)||out FROM digits,args WHERE i<max(length(x),length(y))) SELECT CASE WHEN trim(CASE WHEN carry>0 THEN CAST(carry AS TEXT)||out ELSE out END,'0')='' THEN '0' ELSE CASE WHEN neg THEN '-' ELSE '' END||ltrim(CASE WHEN carry>0 THEN CAST(carry AS TEXT)||out ELSE out END,'0') END FROM digits,args WHERE i=max(length(x),length(y))),report_row_count=report_row_count+1,first_visible_at=min(first_visible_at,excluded.first_visible_at),last_visible_at=max(last_visible_at,excluded.last_visible_at);
 INSERT INTO credit_usage_project_months(organization_id,generation,event_month,project_id,first_visible_at) SELECT NEW.organization_id,NEW.generation,substr(f.event_time,1,7)||'-01',f.project_id,CASE WHEN NEW.source_kind='reservation' THEN f.reserved_at ELSE max(f.reserved_at,f.resolved_at) END FROM (SELECT r.*,x.outcome,x.charge_micros,x.funded_micros,x.quantity,x.rate_card_id,x.meter,x.unit,x.event_time,x.resolved_at FROM metering_projection_reservations r LEFT JOIN metering_projection_resolutions x USING(reservation_id) WHERE r.organization_id=NEW.organization_id AND r.reservation_id=NEW.source_key) f WHERE (NEW.marked=0 OR NOT EXISTS(SELECT 1 FROM credit_usage_reporting_build_applied a WHERE a.organization_id=NEW.organization_id AND a.generation=NEW.generation AND a.source_kind=NEW.source_kind AND a.source_key=NEW.source_key)) AND NEW.source_kind='resolution' AND f.outcome IN('settled','corrected') AND f.event_time NOT IN('infinity','-infinity') ON CONFLICT(organization_id,generation,event_month,project_id) DO UPDATE SET first_visible_at=excluded.first_visible_at WHERE excluded.first_visible_at<first_visible_at;
 INSERT INTO credit_usage_visibility_hot(organization_id,generation,source_kind,source_key,project_id,effective_at,has_positive_hold,dimension_id,event_month) SELECT NEW.organization_id,NEW.generation,NEW.source_kind,NEW.source_key,f.project_id,CASE WHEN NEW.source_kind='reservation' THEN f.reserved_at ELSE max(f.reserved_at,f.resolved_at) END,f.amount_micros>0,CASE WHEN NEW.source_kind='resolution' AND f.outcome IN('settled','corrected') AND f.event_time NOT IN('infinity','-infinity') THEN (SELECT dimension_id FROM credit_usage_dimensions d WHERE d.organization_id=NEW.organization_id AND d.generation=NEW.generation AND d.project_id=f.project_id AND d.environment_id IS f.environment_id AND d.event_month=substr(f.event_time,1,7)||'-01' AND d.rate_card_id=f.rate_card_id AND d.meter=f.meter AND d.unit=f.unit) END,CASE WHEN NEW.source_kind='resolution' AND f.outcome IN('settled','corrected') AND f.event_time NOT IN('infinity','-infinity') THEN substr(f.event_time,1,7)||'-01' END FROM (SELECT r.*,x.outcome,x.charge_micros,x.funded_micros,x.quantity,x.rate_card_id,x.meter,x.unit,x.event_time,x.resolved_at FROM metering_projection_reservations r LEFT JOIN metering_projection_resolutions x USING(reservation_id) WHERE r.organization_id=NEW.organization_id AND r.reservation_id=NEW.source_key) f WHERE (NEW.marked=0 OR NOT EXISTS(SELECT 1 FROM credit_usage_reporting_build_applied a WHERE a.organization_id=NEW.organization_id AND a.generation=NEW.generation AND a.source_kind=NEW.source_kind AND a.source_key=NEW.source_key)) AND (f.amount_micros>0 OR (NEW.source_kind='resolution' AND f.outcome IN('settled','corrected') AND f.event_time NOT IN('infinity','-infinity')));
 INSERT INTO credit_usage_reporting_build_applied SELECT NEW.organization_id,NEW.generation,NEW.source_kind,NEW.source_key FROM (SELECT r.*,x.outcome,x.charge_micros,x.funded_micros,x.quantity,x.rate_card_id,x.meter,x.unit,x.event_time,x.resolved_at FROM metering_projection_reservations r LEFT JOIN metering_projection_resolutions x USING(reservation_id) WHERE r.organization_id=NEW.organization_id AND r.reservation_id=NEW.source_key) f WHERE NEW.marked=1 AND (NEW.marked=0 OR NOT EXISTS(SELECT 1 FROM credit_usage_reporting_build_applied a WHERE a.organization_id=NEW.organization_id AND a.generation=NEW.generation AND a.source_kind=NEW.source_kind AND a.source_key=NEW.source_key)) AND (f.amount_micros>0 OR (NEW.source_kind='resolution' AND f.outcome IN('settled','corrected') AND f.event_time NOT IN('infinity','-infinity'))) ON CONFLICT DO NOTHING;
 DELETE FROM metering_projection_apply WHERE rowid=NEW.rowid;
END;
CREATE TRIGGER metering_projection_apply_source AFTER INSERT ON metering_projection_apply WHEN NEW.family='source' BEGIN
 UPDATE metering_projection_apply SET eligible=CASE WHEN NEW.marked=0 OR NOT EXISTS(SELECT 1 FROM credit_source_build_applied a WHERE a.source_kind=NEW.resource_kind AND a.source_reference=NEW.source_reference AND a.marker_kind=NEW.source_kind AND a.marker_key=NEW.source_key) THEN 1 ELSE 0 END WHERE rowid=NEW.rowid;
 SELECT RAISE(ABORT,'credit_source_source_missing') WHERE NEW.source_kind='valuation' AND (SELECT eligible FROM metering_projection_apply WHERE rowid=NEW.rowid)=1 AND NOT EXISTS(SELECT 1 FROM (SELECT v.*,r.project_id,r.environment_id,r.billing_epoch_id,r.organization_id AS owner,x.meter,x.unit,x.event_time,x.reservation_id AS resolution_id FROM usage_valuations v JOIN metering_projection_reservations r ON r.reservation_id=v.valuation_id LEFT JOIN metering_projection_resolutions x ON x.reservation_id=v.valuation_id WHERE v.source_kind=NEW.resource_kind AND v.source_reference=NEW.source_reference AND v.valuation_id=NEW.source_key) f);
 INSERT INTO credit_source_build_applied SELECT NEW.resource_kind,NEW.source_reference,'valuation',NEW.source_key WHERE NEW.source_kind='valuation' AND NEW.marked=1 AND (SELECT eligible FROM metering_projection_apply WHERE rowid=NEW.rowid)=1 ON CONFLICT DO NOTHING;
 UPDATE credit_source_builds SET status='failed',failure=(SELECT CASE WHEN f.resolution_id IS NULL THEN 'resolution_missing' WHEN EXISTS(SELECT 1 FROM credit_source_heads h WHERE h.source_kind=NEW.resource_kind AND h.source_reference=NEW.source_reference AND h.organization_id<>f.owner) THEN 'organization_conflict' ELSE 'scope_conflict' END FROM (SELECT v.*,r.project_id,r.environment_id,r.billing_epoch_id,r.organization_id AS owner,x.meter,x.unit,x.event_time,x.reservation_id AS resolution_id FROM usage_valuations v JOIN metering_projection_reservations r ON r.reservation_id=v.valuation_id LEFT JOIN metering_projection_resolutions x ON x.reservation_id=v.valuation_id WHERE v.source_kind=NEW.resource_kind AND v.source_reference=NEW.source_reference AND v.valuation_id=NEW.source_key) f),updated_at=(strftime('%Y-%m-%dT%H:%M:%f','now')||'000Z') WHERE NEW.source_kind='valuation' AND NEW.marked=1 AND (SELECT eligible FROM metering_projection_apply WHERE rowid=NEW.rowid)=1 AND source_kind=NEW.resource_kind AND source_reference=NEW.source_reference AND EXISTS(SELECT 1 FROM (SELECT v.*,r.project_id,r.environment_id,r.billing_epoch_id,r.organization_id AS owner,x.meter,x.unit,x.event_time,x.reservation_id AS resolution_id FROM usage_valuations v JOIN metering_projection_reservations r ON r.reservation_id=v.valuation_id LEFT JOIN metering_projection_resolutions x ON x.reservation_id=v.valuation_id WHERE v.source_kind=NEW.resource_kind AND v.source_reference=NEW.source_reference AND v.valuation_id=NEW.source_key) f WHERE NOT(f.resolution_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM credit_source_heads h WHERE h.source_kind=NEW.resource_kind AND h.source_reference=NEW.source_reference AND (h.organization_id<>f.owner OR h.project_id<>f.project_id OR h.environment_id IS NOT f.environment_id OR h.billing_epoch_id<>f.billing_epoch_id OR h.meter<>f.meter OR h.unit<>f.unit OR substr(h.event_time,1,23)<>substr(f.event_time,1,23)))));
 SELECT RAISE(ABORT,'credit_source_inconsistent') WHERE NEW.source_kind='valuation' AND NEW.marked=0 AND (SELECT eligible FROM metering_projection_apply WHERE rowid=NEW.rowid)=1 AND EXISTS(SELECT 1 FROM (SELECT v.*,r.project_id,r.environment_id,r.billing_epoch_id,r.organization_id AS owner,x.meter,x.unit,x.event_time,x.reservation_id AS resolution_id FROM usage_valuations v JOIN metering_projection_reservations r ON r.reservation_id=v.valuation_id LEFT JOIN metering_projection_resolutions x ON x.reservation_id=v.valuation_id WHERE v.source_kind=NEW.resource_kind AND v.source_reference=NEW.source_reference AND v.valuation_id=NEW.source_key) f WHERE NOT(f.resolution_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM credit_source_heads h WHERE h.source_kind=NEW.resource_kind AND h.source_reference=NEW.source_reference AND (h.organization_id<>f.owner OR h.project_id<>f.project_id OR h.environment_id IS NOT f.environment_id OR h.billing_epoch_id<>f.billing_epoch_id OR h.meter<>f.meter OR h.unit<>f.unit OR substr(h.event_time,1,23)<>substr(f.event_time,1,23)))));
 INSERT INTO credit_source_heads(source_kind,source_reference,state,organization_id,project_id,environment_id,billing_epoch_id,meter,unit,event_time,latest_valuation_id,latest_observed_at,latest_rate_card_id,target_quantity,target_charge_micros,target_provider_cost_micros,build_generation) SELECT NEW.resource_kind,NEW.source_reference,CASE WHEN NEW.marked THEN 'building' ELSE 'ready' END,f.owner,f.project_id,f.environment_id,f.billing_epoch_id,f.meter,f.unit,f.event_time,f.valuation_id,f.observed_at,f.rate_card_id,f.target_quantity,f.target_charge_micros,f.target_provider_cost_micros,NEW.generation FROM (SELECT v.*,r.project_id,r.environment_id,r.billing_epoch_id,r.organization_id AS owner,x.meter,x.unit,x.event_time,x.reservation_id AS resolution_id FROM usage_valuations v JOIN metering_projection_reservations r ON r.reservation_id=v.valuation_id LEFT JOIN metering_projection_resolutions x ON x.reservation_id=v.valuation_id WHERE v.source_kind=NEW.resource_kind AND v.source_reference=NEW.source_reference AND v.valuation_id=NEW.source_key) f WHERE NEW.source_kind='valuation' AND (SELECT eligible FROM metering_projection_apply WHERE rowid=NEW.rowid)=1 AND f.resolution_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM credit_source_heads h WHERE h.source_kind=NEW.resource_kind AND h.source_reference=NEW.source_reference AND (h.organization_id<>f.owner OR h.project_id<>f.project_id OR h.environment_id IS NOT f.environment_id OR h.billing_epoch_id<>f.billing_epoch_id OR h.meter<>f.meter OR h.unit<>f.unit OR substr(h.event_time,1,23)<>substr(f.event_time,1,23))) AND NOT EXISTS(SELECT 1 FROM credit_source_heads h WHERE h.source_kind=NEW.resource_kind AND h.source_reference=NEW.source_reference);
 UPDATE credit_source_heads SET event_time=min(credit_source_heads.event_time,f.event_time),latest_tie_ambiguous=CASE WHEN f.observed_at>credit_source_heads.latest_observed_at THEN 0 WHEN f.observed_at=credit_source_heads.latest_observed_at THEN credit_source_heads.latest_tie_ambiguous OR (credit_source_heads.latest_rate_card_id<>f.rate_card_id OR credit_source_heads.target_quantity<>f.target_quantity OR credit_source_heads.target_charge_micros<>f.target_charge_micros OR credit_source_heads.target_provider_cost_micros IS NOT f.target_provider_cost_micros) ELSE credit_source_heads.latest_tie_ambiguous END,revision=credit_source_heads.revision+1,latest_valuation_id=CASE WHEN (f.observed_at>credit_source_heads.latest_observed_at OR (f.observed_at=credit_source_heads.latest_observed_at AND f.valuation_id>credit_source_heads.latest_valuation_id)) THEN f.valuation_id ELSE credit_source_heads.latest_valuation_id END,latest_observed_at=CASE WHEN (f.observed_at>credit_source_heads.latest_observed_at OR (f.observed_at=credit_source_heads.latest_observed_at AND f.valuation_id>credit_source_heads.latest_valuation_id)) THEN f.observed_at ELSE credit_source_heads.latest_observed_at END,latest_rate_card_id=CASE WHEN (f.observed_at>credit_source_heads.latest_observed_at OR (f.observed_at=credit_source_heads.latest_observed_at AND f.valuation_id>credit_source_heads.latest_valuation_id)) THEN f.rate_card_id ELSE credit_source_heads.latest_rate_card_id END,target_quantity=CASE WHEN (f.observed_at>credit_source_heads.latest_observed_at OR (f.observed_at=credit_source_heads.latest_observed_at AND f.valuation_id>credit_source_heads.latest_valuation_id)) THEN f.target_quantity ELSE credit_source_heads.target_quantity END,target_charge_micros=CASE WHEN (f.observed_at>credit_source_heads.latest_observed_at OR (f.observed_at=credit_source_heads.latest_observed_at AND f.valuation_id>credit_source_heads.latest_valuation_id)) THEN f.target_charge_micros ELSE credit_source_heads.target_charge_micros END,target_provider_cost_micros=CASE WHEN (f.observed_at>credit_source_heads.latest_observed_at OR (f.observed_at=credit_source_heads.latest_observed_at AND f.valuation_id>credit_source_heads.latest_valuation_id)) THEN f.target_provider_cost_micros ELSE credit_source_heads.target_provider_cost_micros END FROM (SELECT v.*,r.project_id,r.environment_id,r.billing_epoch_id,r.organization_id AS owner,x.meter,x.unit,x.event_time,x.reservation_id AS resolution_id FROM usage_valuations v JOIN metering_projection_reservations r ON r.reservation_id=v.valuation_id LEFT JOIN metering_projection_resolutions x ON x.reservation_id=v.valuation_id WHERE v.source_kind=NEW.resource_kind AND v.source_reference=NEW.source_reference AND v.valuation_id=NEW.source_key) f WHERE NEW.source_kind='valuation' AND (SELECT eligible FROM metering_projection_apply WHERE rowid=NEW.rowid)=1 AND credit_source_heads.source_kind=NEW.resource_kind AND credit_source_heads.source_reference=NEW.source_reference AND f.resolution_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM credit_source_heads h WHERE h.source_kind=NEW.resource_kind AND h.source_reference=NEW.source_reference AND (h.organization_id<>f.owner OR h.project_id<>f.project_id OR h.environment_id IS NOT f.environment_id OR h.billing_epoch_id<>f.billing_epoch_id OR h.meter<>f.meter OR h.unit<>f.unit OR substr(h.event_time,1,23)<>substr(f.event_time,1,23))) AND (f.observed_at>credit_source_heads.latest_observed_at OR (f.observed_at=credit_source_heads.latest_observed_at AND ((credit_source_heads.latest_rate_card_id<>f.rate_card_id OR credit_source_heads.target_quantity<>f.target_quantity OR credit_source_heads.target_charge_micros<>f.target_charge_micros OR credit_source_heads.target_provider_cost_micros IS NOT f.target_provider_cost_micros) OR f.valuation_id>credit_source_heads.latest_valuation_id)) OR f.event_time<credit_source_heads.event_time);
 SELECT RAISE(ABORT,'credit_source_source_missing') WHERE NEW.source_kind='movement' AND (SELECT eligible FROM metering_projection_apply WHERE rowid=NEW.rowid)=1 AND NOT EXISTS(SELECT 1 FROM (SELECT m.*,g.expires_at,g.granted_at FROM metering_projection_movements m JOIN credit_lots g ON g.organization_id=m.organization_id AND g.grant_id=m.grant_id WHERE m.organization_id=NEW.organization_id AND m.reservation_id=substr(NEW.source_key,1,26) AND m.grant_id=substr(NEW.source_key,28,26) AND m.phase=substr(NEW.source_key,55)) f);
 UPDATE metering_projection_apply SET next_net=(WITH RECURSIVE raw(a,b) AS (SELECT coalesce(coalesce((SELECT net_spent_micros FROM credit_source_grant_allocations a WHERE a.source_kind=NEW.resource_kind AND a.source_reference=NEW.source_reference AND a.grant_id=substr(NEW.source_key,28,26)),'0'),'0'),coalesce((SELECT CAST(spent_micros AS TEXT) FROM (SELECT m.*,g.expires_at,g.granted_at FROM metering_projection_movements m JOIN credit_lots g ON g.organization_id=m.organization_id AND g.grant_id=m.grant_id WHERE m.organization_id=NEW.organization_id AND m.reservation_id=substr(NEW.source_key,1,26) AND m.grant_id=substr(NEW.source_key,28,26) AND m.phase=substr(NEW.source_key,55)) f),'0')), mags AS (SELECT ltrim(a,'-') AS x,ltrim(b,'-') AS y,substr(a,1,1)='-' AS sa,substr(b,1,1)='-' AS sb FROM raw), args AS (SELECT CASE WHEN length(x)>length(y) OR (length(x)=length(y) AND x>=y) THEN x ELSE y END AS x,CASE WHEN length(x)>length(y) OR (length(x)=length(y) AND x>=y) THEN y ELSE x END AS y,CASE WHEN sa=sb THEN 1 ELSE -1 END AS op,CASE WHEN sa=sb OR length(x)>length(y) OR (length(x)=length(y) AND x>=y) THEN sa ELSE sb END AS neg FROM mags), digits(i,carry,out) AS (SELECT 0,0,'' UNION ALL SELECT i+1,CASE WHEN CAST(substr('0'||x,-i-1,1) AS INTEGER)+op*CAST(substr('0'||y,-i-1,1) AS INTEGER)+carry<0 THEN -1 ELSE (CAST(substr('0'||x,-i-1,1) AS INTEGER)+op*CAST(substr('0'||y,-i-1,1) AS INTEGER)+carry)/10 END,CAST((CAST(substr('0'||x,-i-1,1) AS INTEGER)+op*CAST(substr('0'||y,-i-1,1) AS INTEGER)+carry+10)%10 AS TEXT)||out FROM digits,args WHERE i<max(length(x),length(y))) SELECT CASE WHEN trim(CASE WHEN carry>0 THEN CAST(carry AS TEXT)||out ELSE out END,'0')='' THEN '0' ELSE CASE WHEN neg THEN '-' ELSE '' END||ltrim(CASE WHEN carry>0 THEN CAST(carry AS TEXT)||out ELSE out END,'0') END FROM digits,args WHERE i=max(length(x),length(y))),delta=(WITH RECURSIVE raw(a,b) AS (SELECT coalesce(CASE WHEN substr((WITH RECURSIVE raw(a,b) AS (SELECT coalesce(coalesce((SELECT net_spent_micros FROM credit_source_grant_allocations a WHERE a.source_kind=NEW.resource_kind AND a.source_reference=NEW.source_reference AND a.grant_id=substr(NEW.source_key,28,26)),'0'),'0'),coalesce((SELECT CAST(spent_micros AS TEXT) FROM (SELECT m.*,g.expires_at,g.granted_at FROM metering_projection_movements m JOIN credit_lots g ON g.organization_id=m.organization_id AND g.grant_id=m.grant_id WHERE m.organization_id=NEW.organization_id AND m.reservation_id=substr(NEW.source_key,1,26) AND m.grant_id=substr(NEW.source_key,28,26) AND m.phase=substr(NEW.source_key,55)) f),'0')), mags AS (SELECT ltrim(a,'-') AS x,ltrim(b,'-') AS y,substr(a,1,1)='-' AS sa,substr(b,1,1)='-' AS sb FROM raw), args AS (SELECT CASE WHEN length(x)>length(y) OR (length(x)=length(y) AND x>=y) THEN x ELSE y END AS x,CASE WHEN length(x)>length(y) OR (length(x)=length(y) AND x>=y) THEN y ELSE x END AS y,CASE WHEN sa=sb THEN 1 ELSE -1 END AS op,CASE WHEN sa=sb OR length(x)>length(y) OR (length(x)=length(y) AND x>=y) THEN sa ELSE sb END AS neg FROM mags), digits(i,carry,out) AS (SELECT 0,0,'' UNION ALL SELECT i+1,CASE WHEN CAST(substr('0'||x,-i-1,1) AS INTEGER)+op*CAST(substr('0'||y,-i-1,1) AS INTEGER)+carry<0 THEN -1 ELSE (CAST(substr('0'||x,-i-1,1) AS INTEGER)+op*CAST(substr('0'||y,-i-1,1) AS INTEGER)+carry)/10 END,CAST((CAST(substr('0'||x,-i-1,1) AS INTEGER)+op*CAST(substr('0'||y,-i-1,1) AS INTEGER)+carry+10)%10 AS TEXT)||out FROM digits,args WHERE i<max(length(x),length(y))) SELECT CASE WHEN trim(CASE WHEN carry>0 THEN CAST(carry AS TEXT)||out ELSE out END,'0')='' THEN '0' ELSE CASE WHEN neg THEN '-' ELSE '' END||ltrim(CASE WHEN carry>0 THEN CAST(carry AS TEXT)||out ELSE out END,'0') END FROM digits,args WHERE i=max(length(x),length(y))),1,1)='-' THEN '0' ELSE (WITH RECURSIVE raw(a,b) AS (SELECT coalesce(coalesce((SELECT net_spent_micros FROM credit_source_grant_allocations a WHERE a.source_kind=NEW.resource_kind AND a.source_reference=NEW.source_reference AND a.grant_id=substr(NEW.source_key,28,26)),'0'),'0'),coalesce((SELECT CAST(spent_micros AS TEXT) FROM (SELECT m.*,g.expires_at,g.granted_at FROM metering_projection_movements m JOIN credit_lots g ON g.organization_id=m.organization_id AND g.grant_id=m.grant_id WHERE m.organization_id=NEW.organization_id AND m.reservation_id=substr(NEW.source_key,1,26) AND m.grant_id=substr(NEW.source_key,28,26) AND m.phase=substr(NEW.source_key,55)) f),'0')), mags AS (SELECT ltrim(a,'-') AS x,ltrim(b,'-') AS y,substr(a,1,1)='-' AS sa,substr(b,1,1)='-' AS sb FROM raw), args AS (SELECT CASE WHEN length(x)>length(y) OR (length(x)=length(y) AND x>=y) THEN x ELSE y END AS x,CASE WHEN length(x)>length(y) OR (length(x)=length(y) AND x>=y) THEN y ELSE x END AS y,CASE WHEN sa=sb THEN 1 ELSE -1 END AS op,CASE WHEN sa=sb OR length(x)>length(y) OR (length(x)=length(y) AND x>=y) THEN sa ELSE sb END AS neg FROM mags), digits(i,carry,out) AS (SELECT 0,0,'' UNION ALL SELECT i+1,CASE WHEN CAST(substr('0'||x,-i-1,1) AS INTEGER)+op*CAST(substr('0'||y,-i-1,1) AS INTEGER)+carry<0 THEN -1 ELSE (CAST(substr('0'||x,-i-1,1) AS INTEGER)+op*CAST(substr('0'||y,-i-1,1) AS INTEGER)+carry)/10 END,CAST((CAST(substr('0'||x,-i-1,1) AS INTEGER)+op*CAST(substr('0'||y,-i-1,1) AS INTEGER)+carry+10)%10 AS TEXT)||out FROM digits,args WHERE i<max(length(x),length(y))) SELECT CASE WHEN trim(CASE WHEN carry>0 THEN CAST(carry AS TEXT)||out ELSE out END,'0')='' THEN '0' ELSE CASE WHEN neg THEN '-' ELSE '' END||ltrim(CASE WHEN carry>0 THEN CAST(carry AS TEXT)||out ELSE out END,'0') END FROM digits,args WHERE i=max(length(x),length(y))) END,'0'),coalesce(CASE WHEN CASE WHEN substr(coalesce((SELECT net_spent_micros FROM credit_source_grant_allocations a WHERE a.source_kind=NEW.resource_kind AND a.source_reference=NEW.source_reference AND a.grant_id=substr(NEW.source_key,28,26)),'0'),1,1)='-' THEN '0' ELSE coalesce((SELECT net_spent_micros FROM credit_source_grant_allocations a WHERE a.source_kind=NEW.resource_kind AND a.source_reference=NEW.source_reference AND a.grant_id=substr(NEW.source_key,28,26)),'0') END='0' THEN '0' ELSE '-'||CASE WHEN substr(coalesce((SELECT net_spent_micros FROM credit_source_grant_allocations a WHERE a.source_kind=NEW.resource_kind AND a.source_reference=NEW.source_reference AND a.grant_id=substr(NEW.source_key,28,26)),'0'),1,1)='-' THEN '0' ELSE coalesce((SELECT net_spent_micros FROM credit_source_grant_allocations a WHERE a.source_kind=NEW.resource_kind AND a.source_reference=NEW.source_reference AND a.grant_id=substr(NEW.source_key,28,26)),'0') END END,'0')), mags AS (SELECT ltrim(a,'-') AS x,ltrim(b,'-') AS y,substr(a,1,1)='-' AS sa,substr(b,1,1)='-' AS sb FROM raw), args AS (SELECT CASE WHEN length(x)>length(y) OR (length(x)=length(y) AND x>=y) THEN x ELSE y END AS x,CASE WHEN length(x)>length(y) OR (length(x)=length(y) AND x>=y) THEN y ELSE x END AS y,CASE WHEN sa=sb THEN 1 ELSE -1 END AS op,CASE WHEN sa=sb OR length(x)>length(y) OR (length(x)=length(y) AND x>=y) THEN sa ELSE sb END AS neg FROM mags), digits(i,carry,out) AS (SELECT 0,0,'' UNION ALL SELECT i+1,CASE WHEN CAST(substr('0'||x,-i-1,1) AS INTEGER)+op*CAST(substr('0'||y,-i-1,1) AS INTEGER)+carry<0 THEN -1 ELSE (CAST(substr('0'||x,-i-1,1) AS INTEGER)+op*CAST(substr('0'||y,-i-1,1) AS INTEGER)+carry)/10 END,CAST((CAST(substr('0'||x,-i-1,1) AS INTEGER)+op*CAST(substr('0'||y,-i-1,1) AS INTEGER)+carry+10)%10 AS TEXT)||out FROM digits,args WHERE i<max(length(x),length(y))) SELECT CASE WHEN trim(CASE WHEN carry>0 THEN CAST(carry AS TEXT)||out ELSE out END,'0')='' THEN '0' ELSE CASE WHEN neg THEN '-' ELSE '' END||ltrim(CASE WHEN carry>0 THEN CAST(carry AS TEXT)||out ELSE out END,'0') END FROM digits,args WHERE i=max(length(x),length(y))) WHERE rowid=NEW.rowid AND NEW.source_kind='movement' AND (SELECT eligible FROM metering_projection_apply WHERE rowid=NEW.rowid)=1;
 DELETE FROM credit_source_grant_allocations WHERE NEW.source_kind='movement' AND (SELECT eligible FROM metering_projection_apply WHERE rowid=NEW.rowid)=1 AND source_kind=NEW.resource_kind AND source_reference=NEW.source_reference AND grant_id=substr(NEW.source_key,28,26) AND (SELECT next_net FROM metering_projection_apply WHERE rowid=NEW.rowid)='0';
 INSERT INTO credit_source_grant_allocations(source_kind,source_reference,grant_id,net_spent_micros,expires_at,granted_at) SELECT NEW.resource_kind,NEW.source_reference,f.grant_id,(SELECT next_net FROM metering_projection_apply WHERE rowid=NEW.rowid),f.expires_at,f.granted_at FROM (SELECT m.*,g.expires_at,g.granted_at FROM metering_projection_movements m JOIN credit_lots g ON g.organization_id=m.organization_id AND g.grant_id=m.grant_id WHERE m.organization_id=NEW.organization_id AND m.reservation_id=substr(NEW.source_key,1,26) AND m.grant_id=substr(NEW.source_key,28,26) AND m.phase=substr(NEW.source_key,55)) f WHERE NEW.source_kind='movement' AND (SELECT eligible FROM metering_projection_apply WHERE rowid=NEW.rowid)=1 AND f.spent_micros<>0 AND (SELECT next_net FROM metering_projection_apply WHERE rowid=NEW.rowid)<>'0' ON CONFLICT(source_kind,source_reference,grant_id) DO UPDATE SET net_spent_micros=excluded.net_spent_micros;
 UPDATE credit_source_heads SET positive_allocation_total=(WITH RECURSIVE raw(a,b) AS (SELECT coalesce(positive_allocation_total,'0'),coalesce((SELECT delta FROM metering_projection_apply WHERE rowid=NEW.rowid),'0')), mags AS (SELECT ltrim(a,'-') AS x,ltrim(b,'-') AS y,substr(a,1,1)='-' AS sa,substr(b,1,1)='-' AS sb FROM raw), args AS (SELECT CASE WHEN length(x)>length(y) OR (length(x)=length(y) AND x>=y) THEN x ELSE y END AS x,CASE WHEN length(x)>length(y) OR (length(x)=length(y) AND x>=y) THEN y ELSE x END AS y,CASE WHEN sa=sb THEN 1 ELSE -1 END AS op,CASE WHEN sa=sb OR length(x)>length(y) OR (length(x)=length(y) AND x>=y) THEN sa ELSE sb END AS neg FROM mags), digits(i,carry,out) AS (SELECT 0,0,'' UNION ALL SELECT i+1,CASE WHEN CAST(substr('0'||x,-i-1,1) AS INTEGER)+op*CAST(substr('0'||y,-i-1,1) AS INTEGER)+carry<0 THEN -1 ELSE (CAST(substr('0'||x,-i-1,1) AS INTEGER)+op*CAST(substr('0'||y,-i-1,1) AS INTEGER)+carry)/10 END,CAST((CAST(substr('0'||x,-i-1,1) AS INTEGER)+op*CAST(substr('0'||y,-i-1,1) AS INTEGER)+carry+10)%10 AS TEXT)||out FROM digits,args WHERE i<max(length(x),length(y))) SELECT CASE WHEN trim(CASE WHEN carry>0 THEN CAST(carry AS TEXT)||out ELSE out END,'0')='' THEN '0' ELSE CASE WHEN neg THEN '-' ELSE '' END||ltrim(CASE WHEN carry>0 THEN CAST(carry AS TEXT)||out ELSE out END,'0') END FROM digits,args WHERE i=max(length(x),length(y))),revision=revision+1 WHERE NEW.source_kind='movement' AND (SELECT eligible FROM metering_projection_apply WHERE rowid=NEW.rowid)=1 AND source_kind=NEW.resource_kind AND source_reference=NEW.source_reference AND EXISTS(SELECT 1 FROM (SELECT m.*,g.expires_at,g.granted_at FROM metering_projection_movements m JOIN credit_lots g ON g.organization_id=m.organization_id AND g.grant_id=m.grant_id WHERE m.organization_id=NEW.organization_id AND m.reservation_id=substr(NEW.source_key,1,26) AND m.grant_id=substr(NEW.source_key,28,26) AND m.phase=substr(NEW.source_key,55)) f WHERE f.spent_micros<>0);
 INSERT INTO credit_source_build_applied SELECT NEW.resource_kind,NEW.source_reference,'movement',NEW.source_key FROM (SELECT m.*,g.expires_at,g.granted_at FROM metering_projection_movements m JOIN credit_lots g ON g.organization_id=m.organization_id AND g.grant_id=m.grant_id WHERE m.organization_id=NEW.organization_id AND m.reservation_id=substr(NEW.source_key,1,26) AND m.grant_id=substr(NEW.source_key,28,26) AND m.phase=substr(NEW.source_key,55)) f WHERE NEW.source_kind='movement' AND NEW.marked=1 AND (SELECT eligible FROM metering_projection_apply WHERE rowid=NEW.rowid)=1 AND f.spent_micros<>0 ON CONFLICT DO NOTHING;
 DELETE FROM metering_projection_apply WHERE rowid=NEW.rowid;
END;
